document.addEventListener('DOMContentLoaded',function(){window.calls=0;window.shortcut='Mod+Alt+K';window.blocked=false;window.commands=[{id:'save',label:'Save',shortcut:()=>shortcut,disabled:()=>blocked,reason:'Read only',run:()=>{calls++;}},{id:'plain',label:'Plain',run:()=>{calls++;}},{id:'toggle',label:'Toggle',checked:true,shortcut:'Shift+F8',run:()=>{calls++;}}];pudlCommands.register(document.getElementById('scope'),()=>commands.concat([{id:'actions',label:'Actions',items:commands}]));window.redrawDirect=function(){direct.replaceChildren();pudlCommands.rows(direct,commands,scope);};redrawDirect();});